contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // ensure we have enough balance to forward 'value' when executing calls on c later if needed
        if (value > 0) {
            require(address(this).balance >= value, "insufficient balance for forwarded call");
        }

        // Read current minDelay
        uint256 minDelay = c.getMinDelay();

        // We only consider inputs where the provided delay is at least minDelay
        require(delay >= minDelay, "delay must be >= minDelay for this property");

        // Compute operation id
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Ensure operation is not already scheduled
        require(!c.isOperation(id), "operation already scheduled before test");

        // Schedule the operation: this call changes c's state
        // must be a top-level statement
        c.schedule(target, value, data, predecessor, salt, delay);

        // After scheduling, the operation should be recognized as pending (timestamp > _DONE_TIMESTAMP)
        bool pending = c.isOperationPending(id);

        // Attempting to schedule the same operation again should revert; capture that
        bool secondReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule: when scheduling with delay >= minDelay, the operation becomes pending,
        // and a second schedule attempt for the same id reverts.
        assert(pending && secondReverted);
    }

    // allow receiving ETH for forwarding if needed by tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: test behavior of execute w.r.t. EXECUTOR_ROLE openness and reverts
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // we will schedule an operation and then try to execute it
        // ensure we have enough balance to forward 'value' when executing calls on c
        if (value > 0) {
            require(address(this).balance >= value, "insufficient balance");
        }

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // require delay at least current minDelay so scheduling will succeed
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay, "delay < minDelay");

        // operation must not already exist
        require(!c.isOperation(id), "op already exists");

        // schedule the operation (this is a state-changing call on c)
        // caller must have PROPOSER_ROLE; the test contract (this) was not granted any roles by default,
        // so to allow scheduling we require that PROPOSER_ROLE is open (granted to address(0)).
        // We assert that precondition to keep scheduling reachable.
        bytes32 PROPOSER_ROLE = c.PROPOSER_ROLE();
        require(c.hasRole(PROPOSER_ROLE, address(0)), "proposer role not open; cannot schedule");

        c.schedule(target, value, data, predecessor, salt, delay);

        // fast-forward: we cannot change block.timestamp here, but we can only reason about isOperationPending vs ready.
        // Require that delay == minDelay and minDelay == 0 so operation becomes ready immediately to allow execute to proceed.
        // To keep this provable, restrict to case minDelay == 0 and delay == 0 so scheduled op is ready now.
        require(minDelay == 0 && delay == 0, "require minDelay==0 and delay==0 for immediate readiness");
        // check operation is ready
        bool ready = c.isOperationReady(id);
        require(ready, "operation not ready");

        // Now attempt to execute: capture whether it reverts
        bool executedReverted;
        try c.execute{value: value}(target, value, data, predecessor, salt) {
            executedReverted = false;
        } catch {
            executedReverted = true;
        }

        // Determine whether EXECUTOR_ROLE is open; if open, execution should be allowed (not revert) because role open bypasses membership check
        bytes32 EXECUTOR_ROLE = c.EXECUTOR_ROLE();
        bool executorOpen = c.hasRole(EXECUTOR_ROLE, address(0));

        // If executor role is open then execute must NOT revert; otherwise it must revert because this contract lacks the role
        assert(executorOpen ? executedReverted == false : executedReverted == true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: scheduling an operation with a valid delay makes it pending (timestamp > DONE_TIMESTAMP)
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // ensure this test can forward value when calling execute later (not used here but safe)
        if (value > 0) {
            require(address(this).balance >= value, "insufficient balance");
        }

        // Precondition: delay must be at least the contract's minDelay so scheduling should succeed
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay, "delay < minDelay");

        // Only proceed if the operation does not already exist
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id), "op already exists");

        // The test contract must be allowed to schedule: require PROPOSER_ROLE to be open (granted to address(0))
        bytes32 PROPOSER_ROLE = c.PROPOSER_ROLE();
        require(c.hasRole(PROPOSER_ROLE, address(0)), "proposer role not open");

        // Schedule the operation (state-changing call)
        c.schedule(target, value, data, predecessor, salt, delay);

        // After scheduling, the timestamp for id must indicate a pending operation (> DONE_TIMESTAMP)
        // Use the public view getTimestamp via isOperationPending for clarity
        bool pending = c.isOperationPending(id);

        assert(pending);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters: target/value/data/predecessor/salt chosen by the checker; amount to send with execute
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay, uint256 sendAmount) public payable {
        // ensure this contract has enough balance to forward value/sendAmount when calling execute
        if (value + sendAmount > 0) {
            require(address(this).balance >= value + sendAmount, "insufficient balance");
        }

        // Precondition: delay must be at least minDelay so schedule succeeds
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay, "delay < minDelay");

        // Require proposer role to be open so scheduling can be done by anyone
        bytes32 PROPOSER_ROLE = c.PROPOSER_ROLE();
        require(c.hasRole(PROPOSER_ROLE, address(0)), "proposer role not open");

        // Require executor role not to be closed for caller: test will use this contract's executor role
        bytes32 EXECUTOR_ROLE = c.EXECUTOR_ROLE();
        require(c.hasRole(EXECUTOR_ROLE, address(this)), "test contract must have executor role");

        // Compute id and ensure it does not already exist
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id), "operation already exists");

        // Schedule the operation (state-changing call)
        c.schedule(target, value, data, predecessor, salt, delay);

        // Fast-forward condition: require that after scheduling it becomes ready at or before current block.timestamp
        // Because we cannot manipulate time, insist delay == 0 so it's immediately ready
        require(delay == 0, "test requires zero delay to be immediately ready");

        // Now execute the operation as the executor (state-changing call). Forward sendAmount as msg.value.
        // Use try/catch to detect revert but still assert the intended relation below.
        bool reverted;
        try c.execute{value: sendAmount}(target, value, data, predecessor, salt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After a successful execute (not reverted), the operation id must be marked done
        bool done = c.isOperationDone(id);

        // General rule: if execute did not revert, then operation is done
        assert(reverted || done);
    }

    receive() external payable {}
}
